<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/csrf.php';require_once __DIR__.'/layout.php';require_once dirname(__DIR__).'/services/payments.php';
$current=tuman_require_role('TEACHER');$db=tuman_database();$invoices=tuman_teacher_payment_invoices($db,$current['id'],true);$values=['invoice_id'=>'','payment_date'=>gmdate('Y-m-d'),'amount'=>'','payment_method'=>'CASH','reference_number'=>'','remarks'=>''];$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){foreach($values as $key=>$value){$values[$key]=trim((string)($_POST[$key]??''));}if(!tuman_csrf_is_valid($_POST['csrf_token']??null)){$error='Your request could not be verified. Please try again.';}else{try{$id=filter_var($values['invoice_id'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$id){throw new InvalidArgumentException('Choose an invoice.');}tuman_record_payment($db,$current['id'],(int)$id,$values);header('Location: /Tuman/teacher/payments.php?recorded=1');exit;}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable $e){error_log($e->getMessage());$error='Unable to record the payment right now.';}}}tuman_teacher_page_start('Record payment');
?>
<h1>Record payment</h1><p>Selecting an invoice shows its outstanding balance. Entering a higher amount intentionally creates a Student credit.</p><?php if($error): ?><p role="alert"><?= htmlspecialchars($error,ENT_QUOTES,'UTF-8') ?></p><?php endif; ?><form method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(tuman_csrf_token(),ENT_QUOTES,'UTF-8') ?>"><p><label>Invoice <select name="invoice_id" required><option value="">Choose invoice</option><?php foreach($invoices as $invoice): ?><option value="<?= (int)$invoice['id'] ?>"<?= (string)$invoice['id']===$values['invoice_id']?' selected':'' ?>><?= htmlspecialchars($invoice['invoice_number'].' — Due: '.tuman_invoice_money_label($invoice['outstanding_amount'],$invoice['currency_code']).' (total '.tuman_invoice_money_label($invoice['total_amount'],$invoice['currency_code']).')',ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></label></p><p><label>Payment date <input type="date" name="payment_date" required value="<?= htmlspecialchars($values['payment_date'],ENT_QUOTES,'UTF-8') ?>"></label></p><p><label>Amount <input name="amount" inputmode="decimal" required value="<?= htmlspecialchars($values['amount'],ENT_QUOTES,'UTF-8') ?>"></label></p><p><label>Method <select name="payment_method"><?php foreach(TUMAN_PAYMENT_METHODS as $method): ?><option value="<?= $method ?>"<?= $method===$values['payment_method']?' selected':'' ?>><?= htmlspecialchars(str_replace('_',' ',$method),ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></label></p><p><label>Reference <input name="reference_number" maxlength="100" value="<?= htmlspecialchars($values['reference_number'],ENT_QUOTES,'UTF-8') ?>"></label></p><p><label>Remarks <textarea name="remarks" maxlength="500"><?= htmlspecialchars($values['remarks'],ENT_QUOTES,'UTF-8') ?></textarea></label></p><p><button>Record payment</button> <a href="/Tuman/teacher/payments.php">Cancel</a></p></form>
<?php tuman_teacher_page_end(); ?>
